function formatTelephone(e){const n=e.replace(/\D/g,"");if(!n||!((n[0]==="7"||n[0]==="8")&&n.length<=11))return e;const t=(n[0]==="8"?"7"+n.slice(1):n).slice(1,11);let i="+7";return t.length&&(i+=" ("+t.slice(0,3)),t.length>3&&(i+=") "+t.slice(3,6)),t.length>6&&(i+="-"+t.slice(6,8)),t.length>8&&(i+="-"+t.slice(8,10)),i}function telephoneCaretPosition(e,n){if(n<=0)return 0;let r=0;for(let l=0;l<e.length;l++)if(e[l]>="0"&&e[l]<="9"&&(r++,r===n))return l+1;return e.length}function initTelephoneFormat(e){e&&e.addEventListener("input",()=>{const n=e.selectionStart===null?e.value.length:e.selectionStart,r=n===e.value.length,l=e.value.slice(0,n).replace(/\D/g,"").length,t=formatTelephone(e.value);if(t===e.value)return;e.value=t;const i=r?t.length:telephoneCaretPosition(t,l);e.setSelectionRange(i,i)})}window.formatTelephone=formatTelephone,window.initTelephoneFormat=initTelephoneFormat;
